    $(document).ready(function() {
        // --- CORE DATA PARSING AND POPULATION ---
        function populateCardFromData() {
            const rawText = $('#data-source').text();
            if (!rawText) {
                console.error("Data source is empty or not found.");
                return;
            }

            // Helper function to extract content between section headers
            const extractSection = (title, text) => {
                const regex = new RegExp(`【${title}】([\\s\\S]*?)(?=【|$)`);
                const match = text.match(regex);
                return match ? match[1].trim() : '';
            };

            // Helper to parse key-value lines
            const parseKeyValue = (text) => {
                const data = {};
                text.split('\n').filter(Boolean).forEach(line => {
                    const parts = line.split(/：|:/);
                    if (parts.length > 1) {
                        data[parts[0].trim()] = parts.slice(1).join(':').trim();
                    }
                });
                return data;
            };

            // --- Populate Header ---
            const headerData = parseKeyValue(extractSection('版头', rawText));
            $('.card-banner').css('background-image', `url('${headerData['角色卡背景图']}')`);
            $('.character-name').html(headerData['角色卡标题']);
            $('.profile-img').attr('src', headerData['作者头像']);
            $('.author-name').text(headerData['作者姓名']);
            $('.author-bio').text(headerData['作者简介']);
            const mainTags = headerData['角色卡标签'] ? (headerData['角色卡标签'].match(/#(\S+)/g) || []) : [];
            $('.tags').html(mainTags.map(tag => `<div class="tag">${tag}</div>`).join(''));

            // --- Populate Page 1 ---
            const introData = parseKeyValue(extractSection('简要介绍', rawText));
            $('#intro-section').append(Object.keys(introData).map(key => `<p><span class="label">${key}：</span> ${introData[key]}</p>`).join(''));
            $('#story-bg-section').append(`<p>${extractSection('故事背景', rawText).replace(/\n/g, '<br>')}</p>`);
            $('#char-setup-section').append(`<p>${extractSection('角色设定', rawText).replace(/\n/g, '<br>')}</p>`);

            // --- Populate Page 2 ---
            Object.entries({ '游玩指引': '#guide-section', '致谢名单': '#credits-section .custom-details' })
                .forEach(([title, selector]) => {
                    const items = extractSection(title, rawText).split('\n').map(item => item.trim().replace(/^-/, '').trim()).filter(Boolean);
                    if (items.length > 0) {
                        $(selector).append(`<ul>${items.map(item => `<li>${item}</li>`).join('')}</ul>`);
                    }
                });
            $('#notes-section').append(`<p>${extractSection('碎碎念', rawText).replace(/\n/g, '<br>')}</p>`);

            // --- Populate Openings (FIXED) ---
            const openingLines = extractSection('开场导引', rawText).split('\n').filter(Boolean);
            const openingGridHtml = openingLines.map(line => {
                const match = line.match(/^(\d{2})[:：]([\s\S]*)/);
                if (!match) return '';

                const num = parseInt(match[1], 10);
                const dataIndex = num + 1; // Per your request: 01 -> data-index 2
                const fullText = match[2].trim();
                const tags = fullText.match(/#(\S+)/g) || [];
                const tagsHtml = tags.map(tag => `<span class="option-tag">${tag.replace('#', '')}</span>`).join('');
                const mainText = fullText.replace(/#(\S+)/g, '').trim();

                return `<button class="option-button" data-index="${dataIndex}"><span class="option-prefix">${match[1]}</span><span class="option-text">${mainText}</span><div class="option-tag-container">${tagsHtml}</div></button>`;
            }).join('');
            $('.opening-grid').html(openingGridHtml);

            // --- Populate Footer ---
            const footerContent = extractSection('版权信息', rawText).replace(/\n/g, '<br>');
            $('.footer').html(`<p>${footerContent}</p><p class="template-credit">© 2025 电波系 | 角色卡介绍</p>`);
        }

        populateCardFromData();

        // --- UI AND INTERACTIVITY ---
        if (typeof SillyTavern === 'undefined') {
            window.SillyTavern = { chat: [{ swipe_id: undefined, swipes: [], mes: '' }], saveChat: async () => {}, reloadCurrentChat: async () => {} };
        }

        let currentPageIndex = 0;
        const showContentPage = (pageIndex) => {
            $('.content-page').removeClass('active').eq(pageIndex).addClass('active');
            currentPageIndex = pageIndex;
            updateNavButtons();
        };
        const updateNavButtons = () => {
            $('#prevBtn').prop('disabled', currentPageIndex === 0);
            $('#nextBtn').prop('disabled', currentPageIndex === $('.content-page').length - 1);
        };
        showContentPage(0);

        $('#prevBtn').on('click', () => showContentPage(currentPageIndex - 1));
        $('#nextBtn').on('click', () => showContentPage(currentPageIndex + 1));

        const switchSwipe = async (index) => {
            try {
