### 当触发战斗时需要根据经验值判断

let monsterType = "困难";
let currentXP = (typeof user !== 'undefined' && user.经验值) ? user.经验值 : 100;

let reqXP = 0;
if (monsterType === "简单") reqXP = 50;
else if (monsterType === "普通") reqXP = 300;
else if (monsterType === "困难") reqXP = 700;
else if (monsterType === "噩梦") reqXP = 950;

let winRate = currentXP / reqXP;

let narrative = "";
let difficultyClass = "";

if (monsterType === "噩梦" && currentXP < 200) {
    difficultyClass = "必死无疑";
    narrative = "你甚至无法理解眼前存在的形态。理智在尖啸，除了逃跑（如果你还能动的话），别无他法。";
} else if (winRate < 0.3) {
    difficultyClass = "以卵击石";
    narrative = "巨大的实力鸿沟让你感到窒息。你的武器在它坚硬的表皮上只能留下白痕，而它的咆哮足以震碎你的耳膜。";
} else if (winRate < 0.6) {
    difficultyClass = "九死一生";
    narrative = "这是一场极为艰难的战斗，稍有不慎就会命丧当场。你需要利用地形、药物以及所有的运气。";
} else if (winRate < 0.9) {
    difficultyClass = "艰难挑战";
    narrative = "对手很强，你需要全神贯注，寻找它的破绽。";
} else if (winRate < 1.2) {
    difficultyClass = "势均力敌";
    narrative = "旗鼓相当的对手，这将是一场酣畅淋漓的战斗。";
} else {
    difficultyClass = "轻松收割";
    narrative = "这种弱小的生物不值得你拔剑，或许用眼神就能吓退它。";
}
